using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json;
public static class B4Review {
 static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>Repo+"/Docs/검수/2026-11-08_B4_Observation/";static Vector3 origin=new Vector3(0,-66,0);
 static Scene Check(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("Saved B4 edit required");return s;}
 static void Shot(string name,Vector3 pos,Vector3 target,float fov=80){var go=new GameObject("B4Review_Temporary");go.hideFlags=HideFlags.HideAndDontSave;var c=go.AddComponent<Camera>();c.transform.position=origin+pos;c.transform.LookAt(origin+target);c.useOcclusionCulling=false;c.nearClipPlane=.04f;c.farClipPlane=200;c.fieldOfView=fov;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1440,900,24){antiAliasing=4};var old=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1440,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1440,900),0,0);tex.Apply();File.WriteAllBytes(O+name+".png",tex.EncodeToPNG());}finally{RenderTexture.active=old;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
 public static object Capture(){var s=Check();try{Shot("01_arrival",new Vector3(-7,1.7f,4.2f),new Vector3(1,2.0f,1));Shot("02_deck",new Vector3(0,2,-7.5f),new Vector3(0,2.8f,7),86);Shot("03_from_deck",new Vector3(-.3f,4.2f,8.2f),new Vector3(1,1,-2),92);Shot("04_console",new Vector3(2.8f,4.05f,9.30f),new Vector3(3.2f,3.6f,7.85f),65);Shot("05_preparation",new Vector3(1.9f,1.7f,-7.5f),new Vector3(.2f,.95f,-9.65f),60);Shot("06_corridor",new Vector3(-17.5f,1.65f,10.5f),new Vector3(-7.5f,1.5f,4.5f),78);Shot("07_stairs",new Vector3(-3.3f,1.7f,1.5f),new Vector3(-5.8f,2.3f,6.4f),70);}finally{EditorSceneManager.OpenScene(s.path);}return new{images=7};}
 public static object Walk(){var s=Check();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();var saved=player.transform.position;bool enabled=cc.enabled;var results=new List<object>();var routes=new Dictionary<string,Vector3[]>{
 {"corridor_to_center",new[]{new Vector3(-17.6f,0,10.55f),new Vector3(-8.5f,0,5.1f),Vector3.zero}},
 {"left_stairs_up",new[]{new Vector3(-5.8f,0,2.1f),new Vector3(-5.8f,2.5f,7.4f),new Vector3(-5.8f,2.5f,7.8f)}},
 {"right_stairs_up",new[]{new Vector3(5.8f,0,2.1f),new Vector3(5.8f,2.5f,7.4f),new Vector3(5.8f,2.5f,7.8f)}},
 {"deck_crossing",new[]{new Vector3(-5.8f,2.5f,7.8f),new Vector3(-4.9f,2.5f,8.2f),new Vector3(-4.5f,2.5f,9.05f),new Vector3(-3.2f,2.5f,9.55f),new Vector3(0,2.5f,9.6f),new Vector3(3.2f,2.5f,9.55f),new Vector3(4.5f,2.5f,9.05f),new Vector3(4.9f,2.5f,8.2f),new Vector3(5.8f,2.5f,7.8f)}},
 {"left_stairs_down",new[]{new Vector3(-5.8f,2.5f,7.8f),new Vector3(-5.8f,0,2.1f)}},
 {"right_stairs_down",new[]{new Vector3(5.8f,2.5f,7.8f),new Vector3(5.8f,0,2.1f)}},
 {"preparation_access",new[]{Vector3.zero,new Vector3(0,0,-8.4f),new Vector3(3,0,-6.9f),new Vector3(6.2f,0,-5.9f),new Vector3(7.1f,0,.4f)}}};float radius=cc.radius;
 try{foreach(var route in routes){var points=route.Value.Select(v=>v+origin).ToArray();cc.enabled=false;player.transform.position=points[0]+Vector3.up*(cc.height*.5f-cc.center.y+.035f);cc.enabled=true;Physics.SyncTransforms();int steps=0,index=0;bool passed=true;float remaining=0;Vector3 target=points[0];foreach(var to in points.Skip(1)){index++;target=to;int limit=(int)(Vector3.Distance(player.transform.position,to)/.05f)+80;for(int i=0;i<limit;i++){var d=to-player.transform.position;d.y=0;remaining=d.magnitude;if(remaining<.025f)break;cc.Move(d.normalized*Mathf.Min(.05f,remaining)+Vector3.down*.045f);steps++;}if(remaining>.08f){passed=false;break;}}for(int i=0;i<12;i++)cc.Move(Vector3.down*.035f);float bottom=player.transform.position.y+cc.center.y-cc.height*.5f;float error=bottom-target.y;if(Mathf.Abs(error)>.30f)passed=false;results.Add(new{id=route.Key,passed,steps,index,remaining,heightError=error,foot=new[]{player.transform.position.x,bottom,player.transform.position.z}});}}finally{cc.enabled=false;player.transform.position=saved;cc.enabled=enabled;Physics.SyncTransforms();EditorSceneManager.OpenScene(s.path);}
 var result=new{radius,results};File.WriteAllText(O+"walk.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }
 public static object Doors(){var s=Check();try{Shot("door_T03",new Vector3(7.2f,1.7f,-3.6f),new Vector3(10.4f,1.6f,-5.2f),80);Shot("door_T08",new Vector3(5.5f,1.7f,5.5f),new Vector3(8.22f,1.6f,8.22f),80);}finally{EditorSceneManager.OpenScene(s.path);}return new{images=2};}
 public static object Audit(){var s=Check();var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B4_"));var issues=new List<string>();var rr=root.GetComponentsInChildren<Renderer>();var filters=root.GetComponentsInChildren<MeshFilter>();int missing=0;long triangles=0;var materials=rr.SelectMany(r=>r.sharedMaterials).Distinct().ToArray();foreach(var m in materials){if(!m||!m.shader){missing++;continue;}if((m.name.Contains("Display_")||m.name=="B4O_Lamp")&&!m.IsKeywordEnabled("_EMISSION"))issues.Add("No emission "+m.name);}
 foreach(var f in filters){if(!f.sharedMesh){issues.Add("Missing mesh "+f.name);continue;}triangles+=f.sharedMesh.triangles.Length/3;if(f.sharedMesh.isReadable&&f.sharedMesh.vertices.Any(v=>float.IsNaN(v.x)||float.IsNaN(v.y)||float.IsNaN(v.z)))issues.Add("Invalid vertices "+f.name);}
 foreach(var l in root.GetComponentsInChildren<Light>()){if(Vector3.Angle(l.transform.forward,-l.transform.parent.up)>.02f)issues.Add("Wrong light direction "+l.transform.parent.name);if(l.transform.localPosition.magnitude>.1f)issues.Add("Light away from fixture "+l.name);}
 if(missing>0)issues.Add("Missing materials");if(s.GetRootGameObjects().Any(g=>g.name.StartsWith("B5_")))issues.Add("B5 geometry retained");
 var guide=root.GetComponentsInChildren<Transform>().Single(t=>t.name=="B4_T02_C01_GuideLine");float minGuideRadius=guide.GetComponent<MeshFilter>().sharedMesh.vertices.Min(v=>{var p=guide.TransformPoint(v)-origin;return new Vector2(p.x,p.z).magnitude;});if(minGuideRadius<12.2f)issues.Add("Guidance enters dome");
 var result=new{scene=s.path,renderers=rr.Length,colliders=root.GetComponentsInChildren<Collider>().Length,lights=root.GetComponentsInChildren<Light>().Length,triangles,materials=materials.Length,missing,minGuideRadius,issues,assetMeshes=filters.Select(f=>new{asset=AssetDatabase.GetAssetPath(f.sharedMesh),triangles=f.sharedMesh.triangles.Length/3,bounds=f.GetComponent<Renderer>().bounds.size.ToString()}).ToArray()};File.WriteAllText(O+"audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{result.scene,result.renderers,result.colliders,result.lights,result.triangles,result.materials,result.missing,result.minGuideRadius,issues};}
}
